import unicodedata
import psycopg2
import os
import json

def normalize_input(user_input):
    """Normalize unicode input for consistent processing."""
    # NFKC normalization can map different unicode chars to ASCII equivalents
    # e.g., ＇ (U+FF07) -> ' (U+0027), ＝ (U+FF1D) -> = (U+003D)
    normalized = unicodedata.normalize('NFKC', user_input)
    return normalized

def sanitize_for_display(text):
    """Basic sanitization - strips obvious SQL keywords for logging."""
    # This runs BEFORE normalization in the calling code path
    dangerous_keywords = ['DROP', 'DELETE', 'INSERT', 'UPDATE', 'ALTER', '--']
    result = text
    for kw in dangerous_keywords:
        if kw.lower() in result.lower():
            result = result.replace(kw, '[FILTERED]').replace(kw.lower(), '[FILTERED]')
    return result

def get_db_connection():
    """Connect to PostgreSQL database."""
    conn = psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        port=os.environ.get('DB_PORT', '5432'),
        dbname=os.environ.get('DB_NAME', 'appdb'),
        user=os.environ.get('DB_USER', 'lambda_user'),
        password=os.environ.get('DB_PASSWORD', '')
    )
    return conn

def search_products(search_term):
    """Search products by name with unicode-normalized input."""
    # Sanitize first (before normalization - this is the bug)
    sanitized = sanitize_for_display(search_term)

    # Then normalize - unicode chars that bypassed sanitization
    # now become dangerous ASCII equivalents
    normalized = normalize_input(sanitized)

    conn = get_db_connection()
    cursor = conn.cursor()

    # Vulnerable: normalized string injected directly into query
    query = f"SELECT id, name, price, description FROM products WHERE name ILIKE '%{normalized}%'"

    try:
        cursor.execute(query)
        results = cursor.fetchall()
        products = []
        for row in results:
            products.append({
                'id': row[0],
                'name': row[1],
                'price': str(row[2]),
                'description': row[3]
            })
        return products
    except Exception as e:
        return {'error': str(e)}
    finally:
        cursor.close()
        conn.close()

def lambda_handler(event, context):
    """AWS Lambda handler for product search API."""
    try:
        body = json.loads(event.get('body', '{}'))
        search_term = body.get('search', '')

        if not search_term:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'search parameter required'})
            }

        if len(search_term) > 200:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'search term too long'})
            }

        results = search_products(search_term)

        return {
            'statusCode': 200,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps({'results': results})
        }
    except json.JSONDecodeError:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'invalid JSON body'})
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'internal server error'})
        }
